4. Deploy: wrangler publish
5. Set Stripe webhook endpoint to https://your-worker.your-subdomain.workers.dev/webhook
6. Add env variable STRIPE_WEBHOOK_SECRET in Cloudflare dashboard.

1. Create Lambda function (Node.js/Python) with Stripe SDK:
const stripe = require('stripe')(process.env.STRIPE_SECRET_KEY);
exports.handler = async (event) => {
  const sig = event.headers['stripe-signature'];
  const body = event.body;
  let eventObj;
  try {
    eventObj = stripe.webhooks.constructEvent(body, sig, process.env.WEBHOOK_SECRET);
  } catch (err) { return { statusCode: 400, body: 'Signature verification failed' }; }
  // Process event
  return { statusCode: 200, body: 'OK' };
}
2. Create HTTP API in API Gateway, integrate with Lambda.
3. Deploy, get invoke URL.
4. Set Stripe webhook endpoint to that URL.
5. Add environment variables in Lambda console.

1. Create a Next.js app or any framework.
2. Create file pages/api/webhook.js (or api/webhook.ts):
import Stripe from 'stripe';
export default async function handler(req, res) {
  if (req.method !== 'POST') return res.status(405).end();
  const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);
  const sig = req.headers['stripe-signature'];
  let event;
  try {
    event = stripe.webhooks.constructEvent(req.body, sig, process.env.WEBHOOK_SECRET);
  } catch (err) { return res.status(400).send('Signature verification failed'); }
  // Process event
  res.status(200).send('OK');
}
3. Deploy to Vercel via Git.
4. Set Stripe webhook endpoint to https://your-app.vercel.app/api/webhook
5. Add environment variables in Vercel dashboard.
Note: Body parsing must be raw; Vercel may need config to disable body parsing.
